it('wraps non-Error rejections with cause and readable message while rethrowing the original value', async () => {
  const circular: Record<string, unknown> = {};
  circular.self = circular;
  const rejections = ['string boom', {code: 503, detail: 'upstream down'}, undefined, circular];
  const resolved = Symbol('resolved');

  const outcomes = await Promise.all(
    rejections.map(async reason => {
      const seen: Error[] = [];
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          seen.push(error);
        },
      };
      const orchestrator = createChatOrchestrator(createErrorProvider(reason), promptBuilder, undefined, {hooks});
      const thrown = await orchestrator.processMessage(createSession('hello')).then(
        () => resolved,
        (caught: unknown) => caught
      );
      const [firstError] = seen;

      return {
        callCount: seen.length,
        isError: firstError instanceof Error,
        hasMessage: typeof firstError?.message === 'string' && firstError.message.length > 0,
        causeMatches: firstError?.cause === reason,
        rethrownUnchanged: thrown === reason,
      };
    })
  );

